package com.dailyhelp.service;
import com.dailyhelp.entity.*;import com.dailyhelp.repository.*;import org.junit.jupiter.api.*;import org.mockito.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import java.util.*;
class TaskServiceTest { @Mock TaskRepository tasks; @Mock UserRepository users; @InjectMocks TaskService service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);} @Test void getRejectsTaskNotOwnedByUser(){when(tasks.findByIdAndOwnerId(7L,2L)).thenReturn(Optional.empty());assertThrows(NoSuchElementException.class,()->service.get(2L,7L));verify(tasks).findByIdAndOwnerId(7L,2L);} @Test void deleteOnlyDeletesOwnedTask(){Task t=mock(Task.class);when(tasks.findByIdAndOwnerId(7L,2L)).thenReturn(Optional.of(t));service.delete(2L,7L);verify(tasks).delete(t);} }